sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hotel-cta {
    position: relative;
    padding: 75px 25px;
    background: linear-gradient(120deg, #162a22, #1f3a30);
    text-align: center;
    overflow: hidden;
}

.hotel-cta:before,
.hotel-cta:after {
    content: "";
    position: absolute;
    border: 1px solid rgba(230, 199, 156, 0.2);
    border-radius: 50%;
    width: 300px;
    height: 300px;
}

.hotel-cta:before {
    top: -190px;
    left: -100px;
}

.hotel-cta:after {
    bottom: -220px;
    right: -80px;
}

.cta-content {
    position: relative;
    z-index: 1;
}

.cta-eyebrow {
    color: #e6c79c;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
}

.cta-content h2 {
    color: #faf6ef;
    font-family: Georgia, serif;
    font-size: 42px;
    line-height: 1.2;
    margin: 18px 0;
}

.cta-content p {
    color: rgba(250, 246, 239, 0.75);
    font-size: 14px;
    margin-bottom: 28px;
}

.cta-button {
    display: inline-block;
    background: #e6c79c;
    color: #1f3a30 !important;
    padding: 14px 25px;
    text-decoration: none !important;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1px;
    transition: background 0.2s;
}

.cta-button:hover {
    background: #d4b07c;
}

@media (max-width: 767px) {
    .cta-content h2 {
        font-size: 32px;
    }
}
